import{_ as r,o as e,c as i,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2019-07-10 :: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2019-07-10 :: Ceph Orchestration Meeting","date":"2019-07-10T00:00:00.000Z","updated":"2019-07-12T00:00:00.000Z","tags":["Ceph","Orchestrator","Distributed Storage","Testing","CephFS"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-07-10_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2019/2019-07-10_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780460162000}'),l={name:"posts/2019/2019-07-10_-_-_Ceph_Orchestration_Meeting.md"};function o(s,t,n,h,p,_){return e(),i("div",null,[...t[0]||(t[0]=[a('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2019年7月10日</p><p><strong>参会人员</strong>： Kiefer、Sebastian、Yuri、Nathan、Greg、Zach、Liam、Casey、Abby 等</p><p><strong>会议主题</strong>： Ceph 项目开发讨论，包括 Orchestrator 功能改进、测试策略等。</p><p><strong>关键细节</strong>：</p><ul><li><strong>Orchestrator 功能改进</strong>： <ul><li>Kiefer 正在开发一个新的 Orchestrator 功能，用于列出主机并展示主机库存。他计划在 Orchestrator 主页上添加一个新页面，列出所有主机，并展示每个主机的详细信息。</li><li>Christopher 正在研究如何将驱动器组添加到 Safe Dashboard 中，以提供更复杂的存储配置选项。</li></ul></li><li><strong>测试策略</strong>： <ul><li>Nathan 提出了测试 Rook Orchestrator 的问题，并讨论了如何将测试集成到现有的测试套件中。</li><li>Greg 提出了在测试中使用不同部署工具的抽象层，以便与现有的测试套件兼容。</li><li>David 讨论了 Nautilus 释放的情况，包括发现的问题和修复措施。</li></ul></li><li><strong>其他议题</strong>： <ul><li>Liam 讨论了将驱动器组添加到 Safe Dashboard 的合理性。</li><li>Sebastian 提出了使用 SSH Orchestrator 替代 Def Deploy 的可能性。</li></ul></li></ul><p><strong>决定的事项</strong>：</p><ul><li>Kiefer 将继续开发新的 Orchestrator 功能，并将其集成到 Ceph 项目中。</li><li>Christopher 将研究如何将驱动器组添加到 Safe Dashboard 中。</li><li>Nathan 和 Greg 将继续研究测试 Rook Orchestrator 的策略。</li><li>David 将继续修复 Nautilus 释放中发现的问题。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Kiefer 将提供新的 Orchestrator 功能的截图和详细信息。</li><li>Christopher 将提供关于将驱动器组添加到 Safe Dashboard 的更多细节。</li><li>Nathan 和 Greg 将继续与社区讨论测试 Rook Orchestrator 的策略。</li><li>David 将继续修复 Nautilus 释放中发现的问题。</li></ul><p><strong>关键词</strong>：</p><ul><li>Orchestrator</li><li>Dashboard</li><li>Inventory</li><li>Hosts</li><li>Testing</li><li>Rook</li><li>Def Deploy</li><li>SSH</li><li>Nautilus</li><li>Ceph</li></ul>',12)])])}const u=r(l,[["render",o]]);export{c as __pageData,u as default};
